import{_ as a,o as n,c as e,a3 as r}from"./chunks/framework.DFRwgAh-.js";const p=JSON.parse('{"title":"スクラムバン段階別アクティビティ","description":"スクラムバン(Scrumban)は、スクラムの反復的構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル方法論です。","frontmatter":{"title":"スクラムバン段階別アクティビティ","description":"スクラムバン(Scrumban)は、スクラムの反復的構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル方法論です。","head":[["meta",{"name":"keywords","content":"スクラムバン, Scrumban, スクラムバン紹介, スクラムバンの概念, スクラムバンとは, Scrumban紹介, Scrumban概念, スクラムとカンバンの違い, スクラム vs カンバン, アジャイル方法論, アジャイルフレームワーク, カンバン方法論, スクラム方法論, スクラムバンプロセス, スクラムバン運用ガイド, スクラムバンボード, WIP制限, ワークフロー管理, カンバンボードの使い方, スクラムバンのメリット, スクラムバンの特徴, スクラムバンの効果, スクラムバン活用事例, スクラムバン導入効果, スクラムバン Jira設定, スクラムバンボードテンプレート, Scrumbanツール, スクラムバンコラボレーションツール, スクラムバンワークフロー, アジャイルプロジェクト管理, 業務効率化方法論, 反復的作業管理, ボトルネック解消"}],["meta",{"property":"og:title","content":"スクラムバン"}],["meta",{"property":"og:description","content":"スクラムバン(Scrumban)は、スクラムの反復的構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル方法論です。"}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://empasy.io/agile/activity.html"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/ja/agile/activity.html"}]],"sort":400},"headers":[],"relativePath":"ja/agile/activity.md","filePath":"ja/agile/activity.md","lastUpdated":1787636174000}'),i={name:"ja/agile/activity.md"};function s(l,t,d,o,h,g){return n(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="スクラムバン段階別アクティビティガイド" tabindex="-1">スクラムバン段階別アクティビティガイド <a class="header-anchor" href="#スクラムバン段階別アクティビティガイド" aria-label="Permalink to “スクラムバン段階別アクティビティガイド”">​</a></h1><table tabindex="0"><thead><tr><th>段階</th><th>主なアクティビティ</th><th>詳細説明</th></tr></thead><tbody><tr><td><strong>1. Backlog</strong></td><td>- 新規アイデア/リクエストの収集<br>- バックログアイテムの記録<br>- サービス・クラスの指定</td><td>すべての作業の出発点。<br>ビジネスリクエスト、バグ、技術的負債などを <strong>Product Owner</strong> やチームが記録。<br>各カードに <strong>優先順位</strong> と <strong>作業タイプ(緊急・期限固定・標準・無形)</strong> を指定。<br>この段階ではまだ開始準備ができていない状態。</td></tr><tr><td><strong>2. Ready</strong></td><td>- Definition of Ready(DoR)の確認<br>- 作業の分割(必要な場合)<br>- 担当者未指定</td><td>作業がすぐに開始できるように詳細が準備された状態。<br>DoRの基準(要件の明確化、デザイン/リソースの確保、テスト条件の定義など)を満たす必要があります。<br>通常、<strong>補充(Replenishment)ミーティング</strong>でBacklogからReadyに移動。</td></tr><tr><td><strong>3. Doing / In Progress</strong></td><td>- 作業の開始(Pull)<br>- 進行状況のアップデート<br>- ブロッカーの表示</td><td>チームメンバーがWIP制限内でReadyからPullして開始。<br>作業中に発生した <strong>ボトルネック/ブロッカー</strong> はボード上に視覚的に表示(赤いラベル、アイコンなど)。<br>デイリースタンドアップでステータスを共有。</td></tr><tr><td><strong>4. Review (Code Review / Peer Review)</strong></td><td>- コードレビュー/ドキュメントレビューの実行<br>- フィードバックの反映</td><td>開発が終わった作業はレビューカラムに移動。<br>指定されたレビュアーがコードの品質、標準への準拠を確認。<br>レビューフィードバックがあればDoingに戻るか、修正後に再度Review段階へ。</td></tr><tr><td><strong>5. Testing / QA</strong></td><td>- 機能テスト<br>- バグレポートの作成と修正</td><td>QAまたはチームメンバーがテストを実行。<br>自動テスト + 手動テストの併用が可能。<br>バグがあれば該当のカードに記録し、修正後に再検証。</td></tr><tr><td><strong>6. Done</strong></td><td>- Definition of Done(DoD)の満たし確認<br>- ドキュメント作成/リリースノートの更新<br>- デプロイ完了</td><td>すべての品質基準を満たし、デプロイまで完了した状態。<br>リリースノート、ユーザーマニュアルなどのドキュメント作成を含む。<br>カードに完了日を記録(サイクルタイム分析に活用)。</td></tr></tbody></table><hr><h2 id="各段階のアクティビティフローの視覚化" tabindex="-1">各段階のアクティビティフローの視覚化 <a class="header-anchor" href="#各段階のアクティビティフローの視覚化" aria-label="Permalink to “各段階のアクティビティフローの視覚化”">​</a></h2><div class="language-"><button title="Copy code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Backlog]</span></span>
<span class="line"><span>  ↓ (補充ミーティング)</span></span>
<span class="line"><span>[Ready]</span></span>
<span class="line"><span>  ↓ (Pull &amp; WIPチェック)</span></span>
<span class="line"><span>[Doing]</span></span>
<span class="line"><span>  ↓ (開発完了)</span></span>
<span class="line"><span>[Review]</span></span>
<span class="line"><span>  ↓ (レビュー承認)</span></span>
<span class="line"><span>[Testing]</span></span>
<span class="line"><span>  ↓ (品質検証完了)</span></span>
<span class="line"><span>[Done]</span></span></code></pre></div><hr><h2 id="段階別の運用ヒント" tabindex="-1">段階別の運用ヒント <a class="header-anchor" href="#段階別の運用ヒント" aria-label="Permalink to “段階別の運用ヒント”">​</a></h2><h3 id="_1-backlog" tabindex="-1">1. Backlog <a class="header-anchor" href="#_1-backlog" aria-label="Permalink to “1. Backlog”">​</a></h3><ul><li><strong>優先順位基準の明確化</strong>: 緊急度、価値、期限、リスクに基づく</li><li><strong>カードサイズの標準化</strong>: 大きすぎる場合はReadyの前に分割</li><li><strong>定期的な整理</strong>: 古い/不要なカードは破棄</li></ul><h3 id="_2-ready" tabindex="-1">2. Ready <a class="header-anchor" href="#_2-ready" aria-label="Permalink to “2. Ready”">​</a></h3><ul><li><strong>作業着手可能条件(DoR)チェックリスト例</strong><ul><li>要件が明確である</li><li>デザイン/データ/リソースが確保されている</li><li>テスト条件が定義されている</li><li>予想作業時間/範囲が確認されている</li></ul></li></ul><h3 id="_3-doing" tabindex="-1">3. Doing <a class="header-anchor" href="#_3-doing" aria-label="Permalink to “3. Doing”">​</a></h3><ul><li><strong>Stop Starting, Start Finishing (始めることをやめ、終えることを始めよ)</strong> ルールを維持</li><li>ボトルネック発生時は即座に解決を議論</li><li>マルチタスクの最小化</li></ul><h3 id="_4-review" tabindex="-1">4. Review <a class="header-anchor" href="#_4-review" aria-label="Permalink to “4. Review”">​</a></h3><ul><li>コードレビュー基準の定義 (例：コードスタイル、パフォーマンス、セキュリティ、テストの有無)</li><li>レビュー待ち時間を減らすための通知システムの活用</li></ul><h3 id="_5-testing" tabindex="-1">5. Testing <a class="header-anchor" href="#_5-testing" aria-label="Permalink to “5. Testing”">​</a></h3><ul><li>自動テストと手動テストの併用</li><li>バグ発生時は同じカードで修正後に再検証</li><li>テスト失敗時はWIP超過の例外を許可可能</li></ul><h3 id="_6-done" tabindex="-1">6. Done <a class="header-anchor" href="#_6-done" aria-label="Permalink to “6. Done”">​</a></h3><ul><li>完了後、カードに <strong>サイクルタイムを記録</strong></li><li>リリース振り返り時に完了したカードをレビュー</li><li>データ分析用のタグ(バグ、新機能など)を付与</li></ul><hr><h2 id="段階別の主要指標" tabindex="-1">段階別の主要指標 <a class="header-anchor" href="#段階別の主要指標" aria-label="Permalink to “段階別の主要指標”">​</a></h2><table tabindex="0"><thead><tr><th>段階</th><th>核心指標</th><th>活用の目的</th></tr></thead><tbody><tr><td>Backlog → Ready</td><td>リードタイム(リクエスト〜準備完了)</td><td>準備遅延の原因把握</td></tr><tr><td>Ready → Doing</td><td>Pull頻度</td><td>チームの処理能力の把握</td></tr><tr><td>Doing</td><td>平均WIP、ブロッカーの割合</td><td>ボトルネック管理</td></tr><tr><td>Review</td><td>レビュー待ち時間</td><td>品質とスピードのバランス</td></tr><tr><td>Testing</td><td>欠陥率、再作業率</td><td>QAの効率性</td></tr><tr><td>Done</td><td>サイクルタイム、スループット</td><td>予測可能性の改善</td></tr></tbody></table><hr><p>このように整理することで、<strong>スクラムバンを導入したチームが各段階で何をすべきか</strong>が明確になり、 <strong>メトリクスに基づいた改善活動</strong>も並行して行うことができます。</p><hr>`,25)])])}const b=a(i,[["render",s]]);export{p as __pageData,b as default};
